      #{uid}

SELECT id, tenant_id, user_id, coupon_template_id, channel_code, title, coupon_type, img_url,
       user_coupon_code, min_spend_amount, benefit_value, start_time, end_time, status,
       create_time, update_time
FROM pm_coupon_user_rel
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND status = 0
  AND start_time <= #{now}
  AND end_time >= #{now}
ORDER BY end_time ASC, id ASC

