UPDATE pm_coupon_user_rel
SET status = 1
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND id = #{userCouponId}
  AND user_id = #{userId}
  AND status = 0

UPDATE pm_coupon_user_rel
SET status = CASE
        WHEN end_time IS NOT NULL AND end_time < #{now} THEN 2
        ELSE 0
    END
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND id = #{userCouponId}
  AND user_id = #{userId}
  AND status = 1
